const API_BASE = "[http://127.0.0.1:8000/api](http://127.0.0.1:8000/api)";

export const contentFactory = (mode, token) => {
// універсальна функція для створення FormData
const makeFormData = (data) => {
const formData = new FormData();


const safeTitle = data.title || "untitled";
const slug =
  safeTitle.toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + Date.now();

formData.append("title", safeTitle);
formData.append("slug", slug);
formData.append("content", data.content || "");
formData.append("excerpt", data.excerpt || "");
formData.append("is_premium", data.is_premium ? "true" : "false");

// 🔹 type завжди standard, Django не дозволяє "channel"
formData.append("type", "standard");

// категорія для статті
formData.append(
  "category",
  mode === "channel" ? "News" : data.category || "sport"
);

// якщо стаття для каналу — додаємо канал
if (mode === "channel" && data.channel) {
  formData.append("channel", data.channel);
}

// додаємо зображення якщо є
if (data.image) {
  formData.append("image", data.image);
}

return formData;


};

return async (articleData) => {
const formData = makeFormData(articleData);


try {
  const res = await fetch(`${API_BASE}/articles/`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
    },
    body: formData,
  });

  if (!res.ok) {
    const errText = await res.text();
    console.error(
      `❌ Сервер повернув помилку (${mode === "channel" ? "канал" : "звичайна"}):`,
      errText
    );
    throw new Error(
      mode === "channel"
        ? "Не вдалося створити статтю для каналу"
        : "Не вдалося створити стандартну статтю"
    );
  }

  return await res.json();
} catch (err) {
  console.error("Помилка fetch:", err);
  throw err;
}


};
};
